set -eu
D=/root/larkspur-ir; install -d -m700 "$D"; cp -a /etc/nginx/sites-enabled/larkspur "$D/nginx-public.orig"; cp -a /etc/grafana/grafana.ini "$D/grafana.ini.orig"
python3 - <<'PY'
from pathlib import Path
p=Path('/etc/nginx/sites-enabled/larkspur')
s=p.read_text(); s=s.replace('    location ~ \\.php$ {',r'''    # Writable uploads and cache are static-only; forbid symlinks and active file types.
    location ^~ /wp-content/uploads/ {
        disable_symlinks on from=$document_root;
        if ($uri ~* "(?:^|/)[.]|[.](?:php[0-9]*|phtml|phar|pht|php-s)(?:[./]|$)") { return 404; }
        add_header X-Content-Type-Options nosniff always;
        try_files $uri =404;
    }

    location ~ \.php$ {'''); s=s.replace('    location /assets-cache/ {','''    location ^~ /assets-cache/ {
        disable_symlinks on from=/var/www/larkspur-cache;
        if ($uri ~* "(?:^|/)[.]|[.](?:php[0-9]*|phtml|phar|pht|php-s)(?:[./]|$)") { return 404; }
        add_header X-Content-Type-Options nosniff always;'''); s=s.replace('    location ~ /\\.(ht|git) {','    location ~ /\\.(?!well-known/) {'); p.write_text(s)
p=Path('/etc/grafana/grafana.ini'); s=p.read_text(); s=s.replace('[server]\n','[server]\nprotocol = socket\nsocket = /var/lib/larkspur-grafana-proxy/grafana.sock\nrouter_logging = true\n',1); p.write_text(s)
PY
install -d -m0750 -o grafana -g www-data /var/lib/larkspur-grafana-proxy
cat >/etc/nginx/conf.d/larkspur-grafana.conf <<'EOF'
map $http_upgrade $grafana_connection {
    default upgrade;
    '' close;
}
# Never pass a noncanonical path to the old Grafana plugin handler.
# Query arguments are not part of this check.
map $request_uri $grafana_bad_path {
    default 1;
    ~^/(?:[A-Za-z0-9_~@,+:=-]+(?:[.][A-Za-z0-9_~@,+:=-]+)*/)*(?:[A-Za-z0-9_~@,+:=-]+(?:[.][A-Za-z0-9_~@,+:=-]+)*)?(?:[?].*)?$ 0;
}
upstream larkspur_grafana {
    server unix:/var/lib/larkspur-grafana-proxy/grafana.sock;
}
server {
    listen 3000 default_server;
    listen [::]:3000 default_server;
    server_name larkspurcycles.com;
    access_log /var/log/nginx/grafana-proxy.access.log;
    if ($grafana_bad_path) { return 400; }
    location / {
        proxy_http_version 1.1;
        proxy_set_header Host $http_host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $grafana_connection;
        proxy_pass http://larkspur_grafana/;
    }
}
EOF
if ! nginx -t; then cp -a "$D/nginx-public.orig" /etc/nginx/sites-enabled/larkspur; cp -a "$D/grafana.ini.orig" /etc/grafana/grafana.ini; rm /etc/nginx/conf.d/larkspur-grafana.conf; exit 1; fi
service grafana-server restart; ls -l /var/lib/larkspur-grafana-proxy; chmod 0660 /var/lib/larkspur-grafana-proxy/grafana.sock; chgrp www-data /var/lib/larkspur-grafana-proxy/grafana.sock
service nginx reload; sleep 1; curl --max-time 3 -fsS http://127.0.0.1:3000/api/health; curl --max-time 3 -s -o /dev/null -w 'shop=%{http_code}\n' -H 'Host: larkspurcycles.com' http://127.0.0.1/; note 'Isolated Grafana behind a Unix socket and strict canonical path proxy; internal mirror only has 8.3.1 and older. Restricted public writable uploads and cache to static content.'

